questions.solution:
function nullableString(maxLength, version) {
  if (version.startsWith("3.0")) return { type: "string", maxLength, nullable: true };
  return { type: ["string", "null"], maxLength };
}

console.log(JSON.stringify(nullableString(30, "3.0.3"))); // {"type":"string","maxLength":30,"nullable":true}
console.log(JSON.stringify(nullableString(30, "3.1.0"))); // {"type":["string","null"],"maxLength":30}

